mapper.select:
DECLARE @FINDOBJ VARCHAR(5) = #{FINDOBJ} , @FINDWORD VARCHAR(300) = #{FINDWORD} , @EOB_YN VARCHAR(1) = #{EOB_YN};
WITH TEMP1 AS ( SELECT A.DEALER_CD , ISNULL(A.IDT_NO ,'') AS IDT_NO , ISNULL(A.CORP_NO ,'') AS CORP_NO , ISNULL(CONVERT(VARCHAR(10), CONVERT(DATE, A.STRT_YMD), 23),'') AS STRT_YMD , ISNULL(CONVERT(VARCHAR(10), CONVERT(DATE, A.END_YMD), 23) ,'') AS END_YMD , ISNULL(A.DEALER_GB ,'') AS DEALER_GB , ISNULL(A.DEALER_NM ,'') AS DEALER_NM , ISNULL(A.INITIAL_NM ,'') AS INITIAL_NM , ISNULL(A.REP_NM ,'') AS REP_NM , ISNULL(A.BIZ_NM ,'') AS BIZ_NM , ISNULL(A.TYPE_NM ,'') AS TYPE_NM , ISNULL(A.ZIP ,'') AS ZIP , ISNULL(A.ZIP_SEQ ,'') AS ZIP_SEQ , ISNULL(A.ADDR ,'') + ISNULL(A.DTL_ADDR ,'') AS ADDR , ISNULL(A.DTL_ADDR ,'') AS DTL_ADDR , ISNULL(A.J_REGION ,'') AS J_REGION , ISNULL(A.BANK_CD ,'') AS BANK_CD , ISNULL(B1.COM_NM ,'') AS BANKNM , ISNULL(A.BANK_ACNT_NO ,'') AS BANK_ACNT_NO , ISNULL(A.ACNT_HOLDER ,'') AS ACNT_HOLDER , ISNULL(A.EMAIL ,'') AS EMAIL , ISNULL(A.HOMEPG ,'') AS HOMEPG , ISNULL(A.FAX ,'') AS FAX , ISNULL(A.WEB_FAX_YN ,'') AS WEB_FAX_YN , ISNULL(A.SCM_PSWD ,'') AS SCM_PSWD , ISNULL(A.CHRG_ID ,'') AS CHRG_ID , ISNULL(C1.EMP_NM ,'') AS CHRG_NM , ISNULL(A.CHRG_TEL_NO ,'') AS CHRG_TEL_NO , ISNULL(A.CHRG_RGN_NO ,'') AS CHRG_RGN_NO , ISNULL(A.CHRG_HP_NO ,'') AS CHRG_HP_NO , ISNULL(A.CHRG_EMAIL ,'') AS CHRG_EMAIL , ISNULL(A.BFR_DEALER_CD ,'') AS BFR_DEALER_CD , ISNULL(A.BFR_DEALER_NM ,'') AS BFR_DEALER_NM , ISNULL(A.BILL_KIND ,'') AS BILL_KIND , ISNULL(A.BILL_ISSUE_GB ,'') AS BILL_ISSUE_GB , ISNULL(A.PAY_GB ,'') AS PAY_GB , ISNULL(TRY_CONVERT(VARCHAR, A.PAY_TERM) ,'') AS PAY_TERM , ISNULL(TRY_CONVERT(VARCHAR, A.SPPL_LIMIT_DCNT) ,'') AS SPPL_LIMIT_DCNT , ISNULL(A.EOB_YN ,'') AS EOB_YN , ISNULL(A.NOTE ,'') AS NOTE , ISNULL(A.BANKYN ,'') AS BANKYN , ISNULL(A.ENT_DT ,'') AS ENT_DT , CASE WHEN TRY_PARSE(A.ENT_ID AS NUMERIC) IS NULL THEN A.ENT_ID ELSE DBO.FN_USRNM(A.ENT_ID) END AS ENT_ID , ISNULL(A.MFY_DT,'') AS MFY_DT , CASE WHEN TRY_PARSE(A.MFY_ID AS NUMERIC) IS NULL THEN A.MFY_ID ELSE DBO.FN_USRNM(A.MFY_ID ) END AS MFY_ID FROM ACC_DEALER_CD A LEFT JOIN COM_BASE_CD B1 ON A.BANK_CD = B1.COM_CD AND B1.CD_GB = 'BANK_CD' LEFT JOIN HR_EMP_BASIS C1 ON A.CHRG_ID = C1.EMP_ID WHERE 1 = 1 AND ((@FINDWORD = '' AND 1 = 1) OR ((@FINDWORD != '' AND @FINDOBJ = '0') AND (A.DEALER_NM LIKE '%'+@FINDWORD+'%' OR A.INITIAL_NM LIKE '%'+@FINDWORD+'%' )) OR ((@FINDWORD != '' AND @FINDOBJ = '1') AND A.DEALER_CD LIKE '%'+@FINDWORD+'%' ) OR ((@FINDWORD != '' AND @FINDOBJ = '2') AND A.IDT_NO LIKE '%'+@FINDWORD+'%' ) OR ((@FINDWORD != '' AND @FINDOBJ = '3') AND A.REP_NM LIKE '%'+@FINDWORD+'%' ) ) AND ((ISNULL(@EOB_YN,'') = '' AND 1=1)OR(A.EOB_YN = @EOB_YN)) )
SELECT * , (SELECT COUNT(0) FROM TEMP1) AS CNT FROM TEMP1 ORDER BY DEALER_CD ASC OFFSET (#{pageNum}-1)*#{pageLength} ROW FETCH NEXT #{pageLength} ROW ONLY
